import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        long ones = 0, answer = 0;
        char previous = '0';
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '1') ones++;
            else {
                answer += ones;                      // inversions: total distance
                if (previous == '1') answer += ones; // one extra move per zero block
            }
            previous = c;
        }
        System.out.println(answer);
    }
}

