	r := bufio.NewReaderSize(os.Stdin, 1<<20)
	var s string
	fmt.Fscan(r, &s)
	var ones, answer int64
	previous := byte('0')
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '1' {
			ones++
		} else {
			answer += ones // inversions: total distance
			if previous == '1' {
